#!/usr/bin/env python3
"""Render one cell as a self-contained artifact page.

Usage: tools/make_artifact.py TAG [--title "..."] [--out path.html]

Same strict gate as score_cell.py. Emits per-language and per-repo tables, the token-class
split, and the interval — with strata under n=8 marked as noise, because rep30's language
strata are all n<=4 and cannot carry a claim.
"""
import json
import os
import sys
import math
import random
import statistics
import collections

SUITE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CLS = ("input_tokens", "output_tokens", "cache_read_input_tokens", "cache_creation_input_tokens")


def sess(tag, arm, iid):
    d = f"{SUITE}/results/{tag}_r1_{arm}/{arm}/{iid}"
    cc, pd = f"{d}/cc_out.json", f"{d}/patch.diff"
    if not (os.path.isfile(cc) and os.path.getsize(cc) > 0):
        return None
    try:
        j = json.load(open(cc))
    except Exception:
        return None
    if j.get("subtype") != "success":
        return None
    if not (os.path.isfile(pd) and os.path.getsize(pd) > 0):
        return None
    u = j.get("usage") or {}
    return dict(tok=sum(u.get(c, 0) for c in CLS), turns=j.get("num_turns") or 1,
                usd=j.get("total_cost_usd") or 0.0,
                **{c: u.get(c, 0) for c in CLS})


def boot(rs, n=20000):
    if len(rs) < 3:
        return (float("nan"), float("nan"))
    rnd = random.Random(12345)
    gs = [math.exp(sum(math.log(rnd.choice(rs)) for _ in rs) / len(rs)) for _ in range(n)]
    gs.sort()
    return (1 - gs[int(.975 * n)], 1 - gs[int(.025 * n)])


def rows_for(tag, meta):
    root = f"{SUITE}/results/{tag}_r1_eg/eg"
    if not os.path.isdir(root):
        return []
    out = []
    for i in sorted(os.listdir(root)):
        e, b = sess(tag, "eg", i), sess(tag, "baseline", i)
        if e and b:
            m = meta.get(i, {})
            out.append(dict(iid=i, lang=m.get("language") or "—",
                            ratio=e["tok"] / b["tok"], eg=e, base=b))
    return out


def agg(rs):
    r = [x["ratio"] for x in rs]
    g = math.exp(statistics.mean(math.log(v) for v in r))
    se, sb = sum(x["eg"]["tok"] for x in rs), sum(x["base"]["tok"] for x in rs)
    ue, ub = sum(x["eg"]["usd"] for x in rs), sum(x["base"]["usd"] for x in rs)
    return dict(n=len(rs), geo=1 - g, total=1 - se / sb, cost=1 - ue / ub,
                wins=sum(1 for v in r if v < 1),
                egt=statistics.mean(x["eg"]["turns"] for x in rs),
                bat=statistics.mean(x["base"]["turns"] for x in rs))


def cfg(tag):
    """recover the shipped config from the launcher, best effort"""
    for cand in (f"run_{tag.lower()}.sh", f"run_{tag.lower()}_w.sh"):
        p = f"{SUITE}/tools/{cand}"
        if os.path.isfile(p):
            keys = ("CC_MODEL", "CC_EFFORT", "O35_VERIFY_ONLY", "EG_LOC_N", "EG_MCP",
                    "EG_PREFETCH", "EG_VERIFY_MODE", "O35_STRIP_ADVICE", "EG_LITERALS")
            got = {}
            for ln in open(p):
                for k in keys:
                    if ln.startswith(f"export {k}="):
                        got[k] = ln.split("=", 1)[1].strip()
            return got
    return {}


def main():
    tag = sys.argv[1]
    title = sys.argv[sys.argv.index("--title") + 1] if "--title" in sys.argv else f"{tag} — token benchmark"
    out = sys.argv[sys.argv.index("--out") + 1] if "--out" in sys.argv else f"/tmp/{tag}.html"
    meta = {t["instance_id"]: t for t in json.load(open(f"{SUITE}/tasks/rep30_tasks.json"))["instances"]}
    rs = rows_for(tag, meta)
    if not rs:
        sys.exit(f"no gated pairs for {tag}")
    a = agg(rs)
    lo, hi = boot([x["ratio"] for x in rs])
    c = cfg(tag)

    def cls_row(k):
        se = sum(x["eg"][k] for x in rs)
        sb = sum(x["base"][k] for x in rs)
        return (se, sb, (1 - se / sb) * 100 if sb else 0.0)

    bylang = collections.defaultdict(list)
    for x in rs:
        bylang[x["lang"]].append(x)

    H = []
    A = H.append
    A(f"<title>{title}</title>")
    A("""<style>
:root{--ink:#16191F;--paper:#F2F4F6;--panel:#fff;--rule:#D3D9DF;--slate:#5B6672;--faint:#828C97;
--pos:#1F6F5C;--neg:#A6402F;--warn:#9A6A00;--posbg:#E3EFEB;--negbg:#F6E7E4;--warnbg:#F5EEDC;
--mono:ui-monospace,"SF Mono",Menlo,Consolas,monospace;--serif:"Iowan Old Style",Palatino,Georgia,serif;}
@media(prefers-color-scheme:dark){:root{--ink:#E4E8EC;--paper:#101318;--panel:#171B22;--rule:#2C333C;
--slate:#9AA5B1;--faint:#6D7883;--pos:#5FBFA4;--neg:#E08774;--warn:#D6A63F;--posbg:#16302A;--negbg:#33211E;--warnbg:#332B16;}}
:root[data-theme="dark"]{--ink:#E4E8EC;--paper:#101318;--panel:#171B22;--rule:#2C333C;--slate:#9AA5B1;
--faint:#6D7883;--pos:#5FBFA4;--neg:#E08774;--warn:#D6A63F;--posbg:#16302A;--negbg:#33211E;--warnbg:#332B16;}
:root[data-theme="light"]{--ink:#16191F;--paper:#F2F4F6;--panel:#fff;--rule:#D3D9DF;--slate:#5B6672;
--faint:#828C97;--pos:#1F6F5C;--neg:#A6402F;--warn:#9A6A00;--posbg:#E3EFEB;--negbg:#F6E7E4;--warnbg:#F5EEDC;}
