@media(max-width:640px){.wrap{padding:2rem 1rem 3rem;gap:2rem;}body{font-size:16px;}}
h1,h2,.k{font-family:var(--mono);font-weight:600;}
h1{font-size:1.85rem;margin:0;line-height:1.2;text-wrap:balance;}
h2{font-size:.98rem;margin:0 0 .8rem;text-transform:uppercase;letter-spacing:.09em;color:var(--slate);}
p{margin:0 0 .85rem;}p:last-child{margin-bottom:0;}
header{border-bottom:2px solid var(--ink);padding-bottom:1.3rem;display:flex;flex-direction:column;gap:.7rem;}
.meta{font-family:var(--mono);font-size:.73rem;color:var(--faint);text-transform:uppercase;letter-spacing:.11em;}
.hero{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1px;background:var(--rule);
border:1px solid var(--rule);border-radius:3px;overflow:hidden;}
.cellbox{background:var(--panel);padding:1rem 1.1rem;display:flex;flex-direction:column;gap:.25rem;}
.cellbox .lab{font-family:var(--mono);font-size:.67rem;text-transform:uppercase;letter-spacing:.09em;color:var(--faint);}
.cellbox .val{font-family:var(--mono);font-size:1.5rem;font-weight:700;font-variant-numeric:tabular-nums;}
.cellbox .sub{font-family:var(--mono);font-size:.7rem;color:var(--slate);}
.pos{color:var(--pos);}.neg{color:var(--neg);}
.tw{overflow-x:auto;border:1px solid var(--rule);border-radius:3px;background:var(--panel);}
table{border-collapse:collapse;width:100%;font-family:var(--mono);font-size:.775rem;font-variant-numeric:tabular-nums;}
th{text-align:left;font-weight:700;padding:.55rem .75rem;border-bottom:1px solid var(--rule);color:var(--slate);
text-transform:uppercase;letter-spacing:.06em;font-size:.66rem;white-space:nowrap;}
td{padding:.42rem .75rem;border-bottom:1px solid var(--rule);}
tr:last-child td{border-bottom:none;}
td.num{text-align:right;white-space:nowrap;}
.chip{font-family:var(--mono);font-size:.63rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;
padding:.1rem .4rem;border-radius:2px;white-space:nowrap;}
.cn{background:var(--warnbg);color:var(--warn);}
pre{font-family:var(--mono);font-size:.76rem;line-height:1.55;margin:0;background:var(--panel);
border:1px solid var(--rule);border-radius:3px;padding:.85rem .95rem;overflow-x:auto;}
.note{background:var(--panel);border:1px solid var(--rule);border-left:3px solid var(--warn);
border-radius:3px;padding:1rem 1.1rem;}
footer{border-top:1px solid var(--rule);padding-top:1.1rem;font-family:var(--mono);font-size:.72rem;color:var(--faint);line-height:1.7;}
</style>""")
    A('<div class="wrap"><header>')
    A(f'<div class="meta">rep30 · SWE-bench Multilingual · paired vs no-tool control</div>')
    A(f"<h1>{title}</h1>")
    A(f'<p class="meta">cell <strong>{tag}</strong> · n = {a["n"]} gated pairs · strict gate: both arms success + non-empty patch, dropped symmetrically</p>')
    A("</header>")

    sg = "pos" if a["geo"] > 0 else "neg"
    st = "pos" if a["total"] > 0 else "neg"
    sc = "pos" if a["cost"] > 0 else "neg"
    A('<div class="hero">')
    A(f'<div class="cellbox"><div class="lab">geomean</div><div class="val {sg}">{a["geo"]*100:+.1f}%</div>'
      f'<div class="sub">95% CI [{lo*100:+.1f}, {hi*100:+.1f}]</div></div>')
    A(f'<div class="cellbox"><div class="lab">total tokens</div><div class="val {st}">{a["total"]*100:+.1f}%</div>'
      f'<div class="sub">{sum(x["eg"]["tok"] for x in rs)/1e6:.0f}M vs {sum(x["base"]["tok"] for x in rs)/1e6:.0f}M</div></div>')
    A(f'<div class="cellbox"><div class="lab">cost</div><div class="val {sc}">{a["cost"]*100:+.1f}%</div>'
      f'<div class="sub">${sum(x["eg"]["usd"] for x in rs):.0f} vs ${sum(x["base"]["usd"] for x in rs):.0f}</div></div>')
    A(f'<div class="cellbox"><div class="lab">winners</div><div class="val">{a["wins"]}/{a["n"]}</div>'
      f'<div class="sub">turns {a["egt"]:.1f} vs {a["bat"]:.1f}</div></div>')
    A("</div>")

    if c:
        A("<section><h2>Config</h2><pre>" +
          "\n".join(f"{k:20s} {v}" for k, v in c.items()) + "</pre></section>")

    A('<section><h2>By token class</h2><div class="tw"><table>')
    A("<thead><tr><th>class</th><th class='num'>tool</th><th class='num'>control</th><th class='num'>saving</th></tr></thead><tbody>")
    for k, lab in (("cache_read_input_tokens", "cache_read"), ("cache_creation_input_tokens", "cache_creation"),
