#!/usr/bin/env python3
"""Score simrig arms on BEHAVIOUR, not on the token aggregate.

The token aggregate cannot resolve a config at this n -- a full 30-instance cell has a 33-point
geomean CI. These metrics can, because they are counts of what the agent did rather than a ratio
of two noisy sums:

  first_tool    what it reached for on turn 1
  pre_edit      tool calls before the first Edit/Write        <- the headline
  reread_given  Reads/greps of a file whose COMPLETE body was already in the payload  <- TRUST
  grep_calls    shell locate ops
  graph_calls   eg invocations (shell shim or MCP)

Usage: tools/score_simrig.py [arm ...]
"""
import json
import os
import re
import sys
import glob
import statistics
import collections

SUITE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PROJ = os.path.expanduser("~/.claude/projects")
CLS = ("input_tokens", "output_tokens", "cache_read_input_tokens", "cache_creation_input_tokens")

IDX = {}
for p in glob.glob(f"{PROJ}/*/*.jsonl"):
    IDX.setdefault(os.path.basename(p)[:-6], p)

GREP = re.compile(r'^\s*(rg|grep|ag|find|ls)\b')
EG = re.compile(r'entire-graph|eg-q')


def payload_files(d):
    """Files whose complete body the payload already handed over."""
    p = f"{d}/payload.txt"
    if not os.path.isfile(p):
        return set()
    t = open(p, errors="ignore").read()
    return set(re.findall(r'^\d+\.\s+(\S+?):', t, re.M))


def score(d):
    f = f"{d}/out.json"
    if not (os.path.isfile(f) and os.path.getsize(f) > 0):
        return None
    try:
        j = json.load(open(f))
    except Exception:
        return None
    sp = IDX.get(j.get("session_id") or "")
    ev = []
    if sp:
        seen = set()
        for line in open(sp, errors="ignore"):
            try:
                r = json.loads(line)
            except Exception:
                continue
            m = r.get("message") or {}
            if m.get("role") != "assistant":
                continue
            for b in (m.get("content") or []):
                if isinstance(b, dict) and b.get("type") == "tool_use":
                    k = (m.get("id"), b.get("id"))
                    if k in seen:
                        continue
                    seen.add(k)
                    inp = b.get("input") or {}
                    ev.append((b.get("name", ""),
                               str(inp.get("command") or inp.get("file_path") or
                                   inp.get("query") or inp.get("symbol") or "")))
    fe = next((n for n, (t, _) in enumerate(ev) if t in ("Edit", "Write", "MultiEdit")), len(ev))
    given = payload_files(d)

    def touches_given(arg):
        return any(g and (g in arg or arg.endswith(g)) for g in given)

    u = j.get("usage") or {}
    return dict(
        ok=j.get("subtype") == "success",
        patch=os.path.getsize(f"{d}/patch.diff") if os.path.isfile(f"{d}/patch.diff") else 0,
        tok=sum(u.get(c, 0) for c in CLS),
        usd=j.get("total_cost_usd") or 0.0,
        turns=j.get("num_turns") or 0,
        first=(ev[0][0] if ev else "-"),
        pre=fe,
        post=len(ev) - fe,
        grep=sum(1 for t, a in ev if t == "Bash" and GREP.match(a)),
        graph=sum(1 for t, a in ev if t.startswith("mcp__") or (t == "Bash" and EG.search(a))),
        reread=sum(1 for t, a in ev[:fe] if t == "Read" and touches_given(a)),
        n_given=len(given),
    )


def main():
    arms = sys.argv[1:] or sorted(os.path.basename(x) for x in glob.glob(f"{SUITE}/simrig/*")
                                  if os.path.isdir(x))
    print(f"{'arm':<10}{'n':>3}{'first tool':>22}{'pre':>6}{'post':>6}{'grep':>6}{'graph':>7}"
          f"{'reread':>8}{'turns':>7}{'Mtok':>7}{'usd':>7}{'patch':>7}")
    rows = {}
    for arm in arms:
        ss = []
        for d in sorted(glob.glob(f"{SUITE}/simrig/{arm}/*")):
            if os.path.isdir(d):
                s = score(d)
                if s:
                    ss.append(s)
        if not ss:
            print(f"{arm:<10}  (no sessions)")
            continue
        rows[arm] = ss
        first = collections.Counter(s["first"] for s in ss).most_common(1)[0]
        m = lambda k: statistics.mean(s[k] for s in ss)
        print(f"{arm:<10}{len(ss):>3}{first[0][:20]+f'({first[1]})':>22}{m('pre'):>6.1f}{m('post'):>6.1f}"
              f"{m('grep'):>6.1f}{m('graph'):>7.2f}{m('reread'):>8.2f}{m('turns'):>7.1f}"
              f"{m('tok')/1e6:>7.2f}{m('usd'):>7.2f}{sum(1 for s in ss if s['patch']>0):>4}/{len(ss)}")
    if "none" in rows:
        base = statistics.mean(s["pre"] for s in rows["none"])
        print(f"\n  vs the no-tool control (pre-edit {base:.1f}):")
        for arm, ss in rows.items():
            if arm == "none":
                continue
            p = statistics.mean(s["pre"] for s in ss)
            print(f"    {arm:<10} pre-edit {p:>5.1f}   delta {p-base:+5.1f}   "
                  f"=> {-(p-base)*2.38:+5.1f} pt at the measured 2.38pt/call")
    print("\n  reread = Reads, before the first edit, of a file whose complete body was already")
    print("  in the payload. High reread means the agent does not TRUST what it was handed.")


if __name__ == "__main__":
    main()

