#!/usr/bin/env python3
"""EG_VERIFY_PROBE=1 -- strip a VERIFY line whose runner cannot actually start here.

WHY (measured, R30NP n=28, agent-queried graph, no prefetch):
    tier=suite      n=9   -18.9%   narrow  n=13  +19.1%   no VERIFY  n=6  +16.0%
but tier is NOT the discriminator -- laravel shipped a syntactically NARROW
`vendor/bin/phpunit tests/Integration/...` and still lost 72%. The split is whether the
command can run in an UNPROVISIONED checkout:

    RUNS   npm test (node_modules present)      docusaurus +52.3%
           cargo test -p ruff_linter            ruff       +53.3%
    FAILS  cd src && make test (needs C build)  valkey     -64.1%
           bundle exec rake test (needs gems)   faker      -59.9%
           vendor/bin/phpunit  (needs composer) laravel    -72.0%

A command that fails on the ENVIRONMENT rather than the patch sends the agent into
environment repair: 20-34 post-edit calls building throwaway harnesses.

This probe is CHEAP and NEVER runs the suite -- it only asks "could this runner start":
a dry-run, a --version, or a manifest/dir existence check, 5s cap each. Tool OUTPUT only;
it emits no advice and says nothing to the agent beyond removing an unrunnable line.
"""
import os, re, subprocess, sys

REPO = os.environ.get('WT') or os.getcwd()
CAP = float(os.environ.get('EG_PROBE_TIMEOUT', '5'))

def run(cmd, shell=True):
    try:
        r = subprocess.run(cmd, shell=shell, cwd=REPO, capture_output=True, timeout=CAP)
        return r.returncode == 0
    except Exception:
        return False

def probe(cmd):
    """True = the runner can plausibly start. False = strip the line."""
    c = cmd.strip()
    # walk past a leading cd chain -- `cd src && make test` is a normal shape
    m = re.match(r'^cd\s+(\S+)\s*&&\s*(.*)$', c)
    sub = m.group(1) if m else None
    body = m.group(2) if m else c
    base = os.path.join(REPO, sub) if sub else REPO
    tok = body.split()[0] if body.split() else ''

    if tok == 'make':
        # a Makefile must exist AND the target must resolve in a dry run
        if not os.path.isfile(os.path.join(base, 'Makefile')): return False
        tgt = body.split()[1] if len(body.split()) > 1 else ''
        return run(f'make -n {tgt}' if tgt else 'make -n')
    if tok == 'bundle':
        return run('bundle check')                    # gems installed?
    if tok in ('rake',):
        return run('rake -T >/dev/null')
    if 'phpunit' in body:
        exe = body.split()[0]
        p = os.path.join(base, exe) if not exe.startswith('/') else exe
        return os.path.exists(p) and run(f'{exe} --version')
    if tok in ('npm', 'pnpm', 'yarn', 'npx'):
        return os.path.isdir(os.path.join(base, 'node_modules'))
    if tok == 'cargo':
        return run('cargo metadata --no-deps --format-version 1 >/dev/null')
    if tok == 'go':
        return run('go env GOMOD >/dev/null')
    if tok in ('mvn', 'gradle', './gradlew', 'ant'):
        return run(f'{tok} --version >/dev/null')
    if tok in ('python', 'python3', 'pytest'):
        return run('python3 -c "import sys" >/dev/null')
    return True   # unknown runner: leave it alone rather than guess

def main():
    text = sys.stdin.read()
    if os.environ.get('EG_VERIFY_PROBE', '0') != '1':
        sys.stdout.write(text); return
    m = re.search(r'^VERIFY:\s*(.+)$', text, re.M)
    if not m:
        sys.stdout.write(text); return
    if probe(m.group(1)):
        sys.stdout.write(text); return
    # strip the VERIFY line and its indented continuation lines
    out = re.sub(r'^VERIFY:.*(?:\n[ \t]+.*)*\n?', '', text, count=1, flags=re.M)
    sys.stdout.write(out)
    if os.environ.get('GQLOG'):
        try:
            with open(os.environ['GQLOG'] + '.probe', 'a') as f:
                f.write(f'stripped: {m.group(1)[:120]}\n')
        except Exception: pass

if __name__ == '__main__':
    main()
