const cv=document.getElementById("tl");
function draw(){
  const dpr=window.devicePixelRatio||1, W=cv.clientWidth, H=300;
  cv.width=W*dpr; cv.height=H*dpr;
  const g=cv.getContext("2d"); g.scale(dpr,dpr); g.clearRect(0,0,W,H);
  const cs=getComputedStyle(document.documentElement);
  const C={acc:cs.getPropertyValue("--accent").trim(),save:cs.getPropertyValue("--save").trim(),
    cost:cs.getPropertyValue("--cost").trim(),grid:cs.getPropertyValue("--grid").trim(),
    dim:cs.getPropertyValue("--dim").trim(),faint:cs.getPropertyValue("--faint").trim()};
  const T=D.timeline, pad={l:46,r:12,t:14,b:26};
  const lo=Math.min(-40,Math.floor(Math.min(...T.map(t=>t.cum))/10)*10);
  const hi=Math.max(60,Math.ceil(Math.max(...T.map(t=>t.cum))/10)*10);
  const X=i=>pad.l+(i/(T.length-1))*(W-pad.l-pad.r);
  const Y=v=>pad.t+(1-(v-lo)/(hi-lo))*(H-pad.t-pad.b);
  g.font="10px ui-monospace,monospace"; g.textBaseline="middle";
  for(let v=lo;v<=hi;v+=20){
    g.strokeStyle=v===0?C.dim:C.grid; g.lineWidth=v===0?1:1; g.globalAlpha=v===0?.55:1;
    g.beginPath(); g.moveTo(pad.l,Y(v)); g.lineTo(W-pad.r,Y(v)); g.stroke(); g.globalAlpha=1;
    g.fillStyle=C.faint; g.textAlign="right"; g.fillText((v>0?"+":"")+v+"%",pad.l-7,Y(v));
  }
  // per-instance bars
  T.forEach((t,i)=>{
    const y0=Y(0), y1=Y(Math.max(lo,Math.min(hi,t.own)));
    g.fillStyle=t.own>=0?C.save:C.cost; g.globalAlpha=.28;
    g.fillRect(X(i)-1.6,Math.min(y0,y1),3.2,Math.abs(y1-y0)); g.globalAlpha=1;
  });
  // cumulative line
  g.strokeStyle=C.acc; g.lineWidth=2; g.lineJoin="round"; g.beginPath();
  T.forEach((t,i)=>{const x=X(i),y=Y(t.cum); i?g.lineTo(x,y):g.moveTo(x,y)}); g.stroke();
  const last=T[T.length-1];
  g.fillStyle=C.acc; g.beginPath(); g.arc(X(T.length-1),Y(last.cum),3.5,0,7); g.fill();
  g.textAlign="center"; g.fillStyle=C.faint;
  g.fillText("instance completion order  \\u2192",(W+pad.l)/2,H-9);
}
