// MaxDirtyFilesForDigest bounds how much divergence WorktreeContentDigest will
// hash before it gives up. A coding agent mid-task dirties a handful of files;
// a tree with hundreds of differences is a branch switch or a stray build
// output, where hashing every file would cost more than the re-index it saves.
const MaxDirtyFilesForDigest = 64

// ErrWorktreeTooDirty reports that the working tree diverges from HEAD by more
// than MaxDirtyFilesForDigest paths, so no content-exact key was computed.
var ErrWorktreeTooDirty = errors.New("gitutil: working tree has too many changes to digest")

// WorktreeContentDigest returns a stable hex digest naming the working tree's
// content exactly: the HEAD tree hash plus every path that differs from it,
// with the current bytes of each such path.
//
// It exists so a DIRTY working tree can still be cache-keyed. WorktreeMatchesHEAD
// answers "may I reuse the HEAD tree hash as this tree's name" and is false the
// moment anything is edited — which is every query an agent makes after its first
// edit, precisely when re-indexing is most expensive. This function answers the
// stronger question "what IS this tree's name", so the snapshot cache can key on
// the real content instead of refusing to cache at all.
//
// Correctness rests on the same equality WorktreeMatchesHEAD uses: two working
// trees with the same HEAD and the same set of differing paths, each with the
// same bytes, present the same view to a working-tree walk. Ignored files are
// excluded from both sides because `git status` honours .gitignore, matching the
// provider's walk.
//
//   - a clean tree returns "" and nil: the caller should keep using the tree hash;
//   - a deleted path is recorded as deleted rather than hashed, so deletion is
//     distinguishable from an empty file;
//   - renames record both paths, so a rename is not confused with an unrelated
//     pair of add/delete;
//   - a file that vanishes between the status call and the read is recorded as
//     deleted rather than failing the whole digest — the next query re-checks;
//   - more than MaxDirtyFilesForDigest differing paths returns ErrWorktreeTooDirty
//     and the caller falls back to not caching, exactly as before.
func WorktreeContentDigest(ctx context.Context, repo string) (string, error) {
	head, err := RevParse(ctx, repo, "HEAD")
	if err != nil {
		return "", err
	}
	out, err := run(ctx, repo, "git",
		"--no-optional-locks", "status", "--porcelain", "--untracked-files=all", "-z")
	if err != nil {
		return "", err
	}
	paths, err := parsePorcelainZ(out)
	if err != nil {
		return "", err
	}
	if len(paths) == 0 {
		return "", nil
	}
	if len(paths) > MaxDirtyFilesForDigest {
		return "", ErrWorktreeTooDirty
	}
	sort.Slice(paths, func(i, j int) bool { return paths[i].path < paths[j].path })

	hash := sha256.New()
	writePart := func(value string) {
		_, _ = io.WriteString(hash, value)
		_, _ = io.WriteString(hash, "\x00")
	}
	writePart("worktree-content-v1")
	writePart(head)
	for _, entry := range paths {
		writePart(entry.status)
		writePart(entry.path)
		if entry.origin != "" {
			writePart("from")
			writePart(entry.origin)
		}
		digest, err := filedigest.File(filepath.Join(repo, entry.path))
		switch {
		case err == nil:
			writePart(string(digest))
		case errors.Is(err, os.ErrNotExist):
			// Deleted, or removed between the status call and this read.
			writePart("absent")
		default:
			return "", err
		}
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

type porcelainEntry struct {
	status string
	path   string
	origin string // rename/copy source, empty otherwise
}

// parsePorcelainZ splits `git status --porcelain -z` output. Records are
// NUL-terminated `XY <path>`; a rename or copy (R/C in either column) is
// followed by a SECOND NUL-terminated field holding the original path, which is
// why this cannot be a plain split.
func parsePorcelainZ(out string) ([]porcelainEntry, error) {
	fields := strings.Split(out, "\x00")
	entries := make([]porcelainEntry, 0, len(fields))
	for index := 0; index < len(fields); index++ {
		record := fields[index]
		if len(record) == 0 {
			continue
		}
		if len(record) < 4 {
			// "XY " plus at least one path byte; anything shorter is not a record.
			return nil, errors.New("gitutil: malformed porcelain record: " + record)
		}
		status := record[:2]
		entry := porcelainEntry{status: status, path: record[3:]}
		if strings.ContainsAny(status, "RC") {
			index++
			if index >= len(fields) {
				return nil, errors.New("gitutil: rename record missing its source path")
			}
			entry.origin = fields[index]
		}
		entries = append(entries, entry)
	}
	return entries, nil
}

