func worktreeSnapshotCacheable(ctx context.Context, absRepo string, options ProviderSnapshotOptions) bool {
	_, cacheable := worktreeCacheTree(ctx, absRepo, "", options)
	return cacheable
}

// worktreeCacheTree returns the tree component this snapshot must be keyed by,
// and whether it may be cached at all.
//
// For a committed-tree query, and for a working tree that is byte-identical to
// HEAD, the answer is the HEAD tree hash unchanged — so every cache entry
// already on disk keeps its key.
//
// For a DIRTY working tree the answer is the HEAD tree hash joined to a digest
// of exactly what differs from it (gitutil.WorktreeContentDigest). That makes
// the key name the tree's real content, which is what the cache premise
// requires, so a dirty tree becomes cacheable instead of re-indexing on every
// call.
//
// Why this matters: the old rule refused to cache the moment anything was
// edited, which is every query an agent makes AFTER its first edit — measured
// on this repo at 1782 ms/1810 ms back to back against 56 ms warm, and 8.9 s
// search / 22.4 s impact on large repositories. Post-edit is precisely where
// the tool is asked to do its most expensive work.
//
// It stays conservative: any error, or a tree too dirty to digest cheaply,
// falls back to "not cacheable" exactly as before, so a wrong key is never
// preferred to a slow rebuild.
func worktreeCacheTree(
	ctx context.Context,
	absRepo, tree string,
	options ProviderSnapshotOptions,
) (string, bool) {
	if !options.Worktree {
		return tree, true
	}
	if cached, ok := worktreeCleanVerdicts.Load(absRepo); ok {
		verdict := cached.(worktreeCleanVerdict)
		if time.Since(verdict.checkedAt) < worktreeCleanTTL {
			return applyWorktreeDigest(tree, verdict), verdict.cacheable
		}
	}
	verdict := worktreeCleanVerdict{checkedAt: time.Now(), cacheable: true}
	digest, err := gitutil.WorktreeContentDigest(ctx, absRepo)
	switch {
	case err != nil:
		// Not a git repository, no HEAD, too dirty to digest cheaply, or an
		// unreadable file: keep the previous behaviour and bypass the cache.
		verdict.cacheable = false
	case digest == "":
		// Clean: the HEAD tree hash already names this content exactly.
		verdict.clean = true
	default:
		verdict.digest = digest
	}
	worktreeCleanVerdicts.Store(absRepo, verdict)
	return applyWorktreeDigest(tree, verdict), verdict.cacheable
}

// applyWorktreeDigest joins the dirty-content digest to the tree hash. A clean
// tree (empty digest) is returned unchanged so its key is byte-identical to the
// one the previous implementation produced.
func applyWorktreeDigest(tree string, verdict worktreeCleanVerdict) string {
	if verdict.digest == "" {
		return tree
	}
	return tree + "+wt-" + verdict.digest
}

