// hashDirectory folds every regular file under root into hash, in a stable
// order, and reports how many it consumed. It exists for the entries
// `git status` reports as a single directory (a nested repository or worktree):
// the provider's walk sees the files inside, so the key must too.
//
// remaining bounds the walk against the same budget as the top level, so a
// nested repository cannot make this arbitrarily expensive; exceeding it
// returns ErrWorktreeTooDirty and the caller falls back to not caching.
func hashDirectory(hash io.Writer, writePart func(string), root string, remaining int) (int, error) {
	if remaining <= 0 {
		return 0, ErrWorktreeTooDirty
	}
	var files []string
	err := filepath.WalkDir(root, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			return nil
		}
		files = append(files, path)
		if len(files) > remaining {
			return ErrWorktreeTooDirty
		}
		return nil
	})
	if err != nil {
		return 0, err
	}
	sort.Strings(files)
	for _, path := range files {
		writePart(path)
		digest, digestErr := filedigest.File(path)
		switch {
		case digestErr == nil:
			writePart(digest.Hash)
			writePart(strconv.FormatInt(digest.Bytes, 10))
		case errors.Is(digestErr, os.ErrNotExist):
			writePart("absent")
		default:
			return 0, digestErr
		}
	}
	return len(files), nil
}

