package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/entire-graph/internal/gitutil"
	"github.com/entireio/entire-graph/internal/sem"
)

// changed answers the question every other verb refuses: WHAT DID I JUST EDIT,
// AND WHAT ELSE NEEDS IT.
//
// Why it exists. `diff`/`analyze` compare two refs; `diff --base HEAD --head HEAD`
// returns no files, so no verb could see an uncommitted edit at all. Yet the
// measured cost of a coding session is overwhelmingly POST-edit: on the rep50
// corpus 97.7% of the token difference between the graph arm and a no-tool
// baseline landed after the first Edit, where the agent re-greps for callers,
// re-reads what it just wrote, and hunts for the sites that share the defect.
// Those are graph questions asked about the working tree, and the graph could
// not answer them.
//
// It reuses the existing pieces rather than adding a second pipeline: git for
// the hunks, the ordinary working-tree snapshot for symbols and relations. The
// snapshot is the same one `search` builds, so it is served from the same cache.
type changedResponse struct {
	RepoRoot string `json:"repo_root"`
	Head     string `json:"head"`
	// Files is every path that differs from HEAD, whether or not the graph
	// resolved a symbol inside it, so a caller can see coverage rather than
	// guess at it.
	Files []changedFile `json:"files"`
	// Symbols are the definitions whose bodies overlap a changed hunk, each with
	// the sites that depend on it.
	Symbols            []changedSymbol      `json:"symbols"`
	Warnings           []sem.ProviderWarning `json:"warnings,omitempty"`
	PartialFailures    []sem.PartialFailure  `json:"partial_failures"`
	IndexCacheHit      bool                  `json:"index_cache_hit"`
	IndexCacheDisabled bool                  `json:"index_cache_disabled,omitempty"`
	IndexLatencyMS     int64                 `json:"index_latency_ms"`
	QueryLatencyMS     int64                 `json:"query_latency_ms"`
	TotalLatencyMS     int64                 `json:"total_latency_ms"`
}

type changedFile struct {
	Path string `json:"path"`
	// Status is git's porcelain letter: M, A, D, R, ? for untracked.
	Status string `json:"status"`
	// Hunks are the changed line ranges in the CURRENT file. A deleted or
	// untracked-binary file has none.
	Hunks []changedHunk `json:"hunks,omitempty"`
	// SymbolsResolved reports whether the graph mapped any hunk in this file to
	// a definition. False for a file the parser does not cover, which is a
	// coverage fact the caller should see rather than infer from an empty list.
	SymbolsResolved bool `json:"symbols_resolved"`
}

type changedHunk struct {
	StartLine int `json:"start_line"`
	EndLine   int `json:"end_line"`
}

type changedSymbol struct {
	Symbol neighborEndpoint `json:"symbol"`
	// Callers are the in-repo sites that call this symbol. These are the places
	// a contract change has to be reconciled with, and the reason this verb
	// exists: after an edit they are otherwise found by grep.
	Callers []neighborEndpoint `json:"callers"`
	// CallerCount is the total before Limit truncation, so a truncated answer
	// still reports the true blast radius.
	CallerCount int `json:"caller_count"`
}

type changedFlags struct {
	commonFlags
	Limit int
}

func parseChangedFlags(args []string) (changedFlags, error) {
	flags := changedFlags{Limit: 20}
	common, rest, err := parseCommonFlags(args)
	if err != nil {
		return flags, err
	}
	flags.commonFlags = common
	for index := 0; index < len(rest); index++ {
		switch rest[index] {
		case "--limit":
			index++
			if index >= len(rest) {
				return flags, errors.New("--limit requires a value")
			}
			value, convErr := strconv.Atoi(rest[index])
			if convErr != nil || value < 0 {
				return flags, fmt.Errorf("--limit expects a non-negative integer, got %q", rest[index])
			}
			flags.Limit = value
		default:
			return flags, fmt.Errorf("unknown flag for changed: %q", rest[index])
		}
	}
	return flags, nil
}

func runChanged(ctx context.Context, opts Options, args []string) error {
	flags, err := parseChangedFlags(args)
	if err != nil {
		return err
	}
	repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
	if err != nil {
		return err
	}
	profile, err := parseProfile(flags.Profile)
	if err != nil {
		return err
	}
	cacheDir := resolveCacheDir(flags.CacheDir, opts.Env.PluginDataDir)

	totalStarted := time.Now()
	files, err := gitutil.WorktreeChangedFiles(ctx, repo)
	if err != nil {
		return err
	}

	indexStarted := time.Now()
	// The working tree is the whole point of this verb, so Worktree is forced on
	// rather than taken from the flag: a committed-tree snapshot cannot contain
	// the edit being asked about.
	snapshot, cacheHit, err := sem.LoadOrBuildProviderSnapshot(ctx, repo, opts.Version, sem.ProviderSnapshotOptions{
		NoNetwork:    true,
		Worktree:     true,
		IgnoreFiles:  flags.IgnoreFile,
		IncludeFiles: flags.IncludeFile,
		Profile:      profile,
	}, cacheDir, flags.DisableCache)
	if err != nil {
		return err
	}
	indexLatency := time.Since(indexStarted)

	queryStarted := time.Now()
	response := buildChangedResponse(snapshot, files, flags.Limit)
	response.RepoRoot = snapshot.Header.RepoRoot
	response.Head = snapshot.Header.Commit
	response.Warnings = snapshot.Header.Warnings
	response.PartialFailures = snapshot.Header.PartialFailures
	response.IndexCacheHit = cacheHit
	response.IndexCacheDisabled = cacheDir == "" || flags.DisableCache
	response.IndexLatencyMS = indexLatency.Milliseconds()
	response.QueryLatencyMS = time.Since(queryStarted).Milliseconds()
	response.TotalLatencyMS = time.Since(totalStarted).Milliseconds()

	if flags.Format == "json" {
		encoder := json.NewEncoder(opts.Stdout)
		encoder.SetIndent("", "  ")
		return encoder.Encode(response)
	}
	writeChangedText(opts, response)
	return nil
}

// buildChangedResponse maps hunks to the definitions that contain them, then
// collects each definition's in-repo callers from the same relation stream
// `impact` reads. One pass over relations, not one per symbol.
func buildChangedResponse(snapshot sem.ProviderSnapshot, files []gitutil.WorktreeChange, limit int) changedResponse {
	response := changedResponse{Files: make([]changedFile, 0, len(files))}

	changedByPath := make(map[string][]changedHunk, len(files))
	for _, file := range files {
		hunks := make([]changedHunk, 0, len(file.Hunks))
		for _, hunk := range file.Hunks {
			hunks = append(hunks, changedHunk{StartLine: hunk.StartLine, EndLine: hunk.EndLine})
		}
		changedByPath[filepath.ToSlash(file.Path)] = hunks
	}

	// Definitions whose span overlaps a changed hunk. A file with no hunks
	// (untracked, or wholly new) counts every definition in it as changed,
	// because all of it is new.
	touched := map[string]sem.SymbolRecord{}
	resolved := map[string]bool{}
	for _, symbol := range snapshot.Symbols {
		path := filepath.ToSlash(symbol.FilePath)
		hunks, ok := changedByPath[path]
		if !ok {
			continue
		}
		if len(hunks) == 0 || symbolOverlapsHunks(symbol, hunks) {
			touched[symbol.ID] = symbol
			resolved[path] = true
		}
	}

	for _, file := range files {
		path := filepath.ToSlash(file.Path)
		response.Files = append(response.Files, changedFile{
			Path:            path,
			Status:          file.Status,
			Hunks:           changedByPath[path],
			SymbolsResolved: resolved[path],
		})
	}

	if len(touched) == 0 {
		response.Symbols = []changedSymbol{}
		return response
	}

	endpoints := make(map[string]neighborEndpoint, len(snapshot.Symbols)+len(snapshot.Externals))
	for _, symbol := range snapshot.Symbols {
		endpoints[symbol.ID] = endpointForSymbol(symbol)
	}

	callers := make(map[string][]neighborEndpoint, len(touched))
	seen := map[string]bool{}
	for _, relation := range snapshot.Relations {
		if !impactCallRelation(relation.Type) {
			continue
		}
		if _, ok := touched[relation.ToID]; !ok {
			continue
		}
		// A definition calling itself, or another hunk in the same edit, is not
		// a site that needs reconciling — it is part of what was just written.
		if _, alsoChanged := touched[relation.FromID]; alsoChanged {
			continue
		}
		endpoint, ok := endpoints[relation.FromID]
		if !ok {
			continue
		}
		key := relation.ToID + "\x00" + relation.FromID
		if seen[key] {
			continue
		}
		seen[key] = true
		callers[relation.ToID] = append(callers[relation.ToID], endpoint)
	}

	response.Symbols = make([]changedSymbol, 0, len(touched))
	for id, symbol := range touched {
		entry := changedSymbol{Symbol: endpointForSymbol(symbol)}
		found := callers[id]
		entry.CallerCount = len(found)
		sort.Slice(found, func(i, j int) bool {
			if found[i].FilePath != found[j].FilePath {
				return found[i].FilePath < found[j].FilePath
			}
			return found[i].StartLine < found[j].StartLine
		})
		if limit > 0 && len(found) > limit {
			found = found[:limit]
		}
		entry.Callers = found
		response.Symbols = append(response.Symbols, entry)
	}
	// Most-depended-on first: that is the order in which a reviewer should
	// reconcile the edit, and it puts the risky change at the top.
	sort.Slice(response.Symbols, func(i, j int) bool {
		if response.Symbols[i].CallerCount != response.Symbols[j].CallerCount {
			return response.Symbols[i].CallerCount > response.Symbols[j].CallerCount
		}
		if response.Symbols[i].Symbol.FilePath != response.Symbols[j].Symbol.FilePath {
			return response.Symbols[i].Symbol.FilePath < response.Symbols[j].Symbol.FilePath
		}
		return response.Symbols[i].Symbol.StartLine < response.Symbols[j].Symbol.StartLine
	})
	return response
}

// symbolOverlapsHunks reports whether a definition's span intersects any changed
// line range. Both are inclusive 1-based line numbers.
func symbolOverlapsHunks(symbol sem.SymbolRecord, hunks []changedHunk) bool {
	start, end := symbol.StartLine, symbol.EndLine
	if end < start {
		end = start
	}
	for _, hunk := range hunks {
		if hunk.StartLine <= end && start <= hunk.EndLine {
			return true
		}
	}
	return false
}

func writeChangedText(opts Options, response changedResponse) {
	if len(response.Files) == 0 {
		fmt.Fprintln(opts.Stdout, "No uncommitted changes.")
		return
	}
	fmt.Fprintf(opts.Stdout, "CHANGED vs %s — %d file(s)\n\n", shortCommit(response.Head), len(response.Files))
	for _, file := range response.Files {
		marker := ""
		if !file.SymbolsResolved {
			marker = "  (no definitions resolved)"
		}
		fmt.Fprintf(opts.Stdout, "  %s %s%s\n", file.Status, file.Path, marker)
	}
	if len(response.Symbols) == 0 {
		fmt.Fprintln(opts.Stdout, "\nNo changed definitions resolved.")
		return
	}
	fmt.Fprintf(opts.Stdout, "\nCHANGED DEFINITIONS — %d, most-depended-on first\n", len(response.Symbols))
	for _, entry := range response.Symbols {
		fmt.Fprintf(opts.Stdout, "\n%s:%d  %s %s  (%d caller(s))\n",
			entry.Symbol.FilePath, entry.Symbol.StartLine, entry.Symbol.Kind,
			entry.Symbol.Name, entry.CallerCount)
		for _, caller := range entry.Callers {
			fmt.Fprintf(opts.Stdout, "    <- %s:%d  %s\n", caller.FilePath, caller.StartLine, caller.Name)
		}
		if entry.CallerCount > len(entry.Callers) {
			fmt.Fprintf(opts.Stdout, "    ... %d more\n", entry.CallerCount-len(entry.Callers))
		}
	}
}

func shortCommit(commit string) string {
	if len(commit) > 8 {
		return commit[:8]
	}
	if commit == "" {
		return "HEAD"
	}
	return strings.TrimSpace(commit)
}

