// WorktreeChange is one path that differs from HEAD, with the line ranges that
// differ in the file as it exists NOW.
type WorktreeChange struct {
	Path   string
	Status string // git porcelain letter: M, A, D, R, or ? for untracked
	Hunks  []WorktreeHunk
}

// WorktreeHunk is an inclusive 1-based line range in the current file.
type WorktreeHunk struct {
	StartLine int
	EndLine   int
}

// WorktreeChangedFiles reports every path that differs from HEAD together with
// the changed line ranges, covering BOTH tracked modifications and untracked
// files.
//
// It exists because the ref-to-ref diff cannot answer it: `git diff HEAD HEAD`
// is empty by definition, so a verb built on ChangedFiles can never see an
// uncommitted edit. Post-edit is where a coding agent spends most of its
// budget, so that gap is the expensive one.
//
// Untracked files have no diff to parse, so they report status "?" with no
// hunks; callers treat "no hunks" as "all of it is new". A deleted file
// likewise carries no hunks in the current tree.
func WorktreeChangedFiles(ctx context.Context, repo string) ([]WorktreeChange, error) {
	if _, err := RevParse(ctx, repo, "HEAD"); err != nil {
		return nil, err
	}
	// -U0 so hunk headers bound exactly the changed lines rather than context.
	out, err := run(ctx, repo, "git",
		"--no-optional-locks", "diff", "-U0", "--no-color", "--no-ext-diff", "HEAD")
	if err != nil {
		return nil, err
	}
	byPath := map[string]*WorktreeChange{}
	order := []string{}
	var current *WorktreeChange
	for _, line := range strings.Split(out, "\n") {
		switch {
		case strings.HasPrefix(line, "+++ b/"):
			path := strings.TrimPrefix(line, "+++ b/")
			if path == "/dev/null" {
				current = nil
				continue
			}
			if existing, ok := byPath[path]; ok {
				current = existing
				continue
			}
			change := &WorktreeChange{Path: path, Status: "M"}
			byPath[path] = change
			order = append(order, path)
			current = change
		case strings.HasPrefix(line, "@@") && current != nil:
			if hunk, ok := parseUnifiedHunkNewRange(line); ok {
				current.Hunks = append(current.Hunks, hunk)
			}
		}
	}
	// Untracked files never appear in `git diff`, but the provider's walk
	// indexes them, so a new file's definitions would otherwise be invisible.
	status, err := run(ctx, repo, "git",
		"--no-optional-locks", "status", "--porcelain", "--untracked-files=all", "-z")
	if err != nil {
		return nil, err
	}
	entries, err := parsePorcelainZ(status)
	if err != nil {
		return nil, err
	}
	for _, entry := range entries {
		if !strings.HasPrefix(entry.status, "??") {
			continue
		}
		if _, seen := byPath[entry.path]; seen {
			continue
		}
		change := &WorktreeChange{Path: entry.path, Status: "?"}
		byPath[entry.path] = change
		order = append(order, entry.path)
	}
	changes := make([]WorktreeChange, 0, len(order))
	for _, path := range order {
		changes = append(changes, *byPath[path])
	}
	sort.Slice(changes, func(i, j int) bool { return changes[i].Path < changes[j].Path })
	return changes, nil
}

// parseUnifiedHunkNewRange reads the NEW-file range out of a unified hunk
// header: `@@ -old,count +new,count @@`. A count of 0 means a pure deletion,
// which has no lines in the current file and is skipped.
func parseUnifiedHunkNewRange(header string) (WorktreeHunk, bool) {
	plus := strings.Index(header, "+")
	if plus < 0 {
		return WorktreeHunk{}, false
	}
	rest := header[plus+1:]
	if end := strings.IndexAny(rest, " @"); end >= 0 {
		rest = rest[:end]
	}
	startText, countText, hasCount := strings.Cut(rest, ",")
	start, err := strconv.Atoi(startText)
	if err != nil {
		return WorktreeHunk{}, false
	}
	count := 1
	if hasCount {
		parsed, convErr := strconv.Atoi(countText)
		if convErr != nil {
			return WorktreeHunk{}, false
		}
		count = parsed
	}
	if count <= 0 {
		return WorktreeHunk{}, false
	}
	return WorktreeHunk{StartLine: start, EndLine: start + count - 1}, true
}
