	// Scoped hits are rarely the globally top-ranked ones -- that is precisely why the caller
	// scoped -- so the fetch has to be deep enough that the filter has something to keep.
	pathScopeOverfetch = 12
	pathScopeMaxFetch  = 200
)

// pathScopeMatches reports whether a result path is inside one of the scopes the caller named.
//
// Three forms, because those are the three the recorded greps use:
//   - an exact file            tests/Validation/ValidationValidatorTest.php
//   - a directory prefix       tests/Validation/   (and the bare `tests/Validation`)
//   - a glob                   packages/*/src/*.ts, *_test.go
//
// Matching is on the repo-relative slash path, and a bare glob with no separator is also tried
// against the basename, so `--path "*_test.go"` behaves the way `find -name` trained everyone to
// expect rather than silently matching nothing.
func pathScopeMatches(filePath string, scopes []string) bool {
	clean := strings.TrimPrefix(path.Clean(strings.ReplaceAll(filePath, "\\", "/")), "./")
	for _, raw := range scopes {
		scope := strings.TrimPrefix(path.Clean(strings.TrimSpace(strings.ReplaceAll(raw, "\\", "/"))), "./")
		if scope == "" || scope == "." {
			continue
		}
		if clean == scope || strings.HasPrefix(clean, scope+"/") {
			return true
		}
		if ok, err := path.Match(scope, clean); err == nil && ok {
			return true
		}
		if !strings.Contains(scope, "/") {
			if ok, err := path.Match(scope, path.Base(clean)); err == nil && ok {
				return true
			}
		}
	}
	return false
}

// applyPathScope keeps the in-scope results, truncated to the caller's original top-k.
//
// NEVER-EMPTY. If nothing in the ranked pool is in scope, the unscoped head is returned instead.
// A refusal is the worst outcome this tool can produce: across the rep50 sessions the calls that
// came back with nothing were all `def` or `grep`, and 3 of 4 live sessions abandoned the tool
// permanently after a single one. A scope that matches nothing is a narrowing hint that failed,
// not a reason to answer nothing.
func applyPathScope(results []sem.SearchResult, scopes []string, topK int) []sem.SearchResult {
	if len(results) == 0 || len(scopes) == 0 {
		return results
	}
	kept := make([]sem.SearchResult, 0, len(results))
	for _, result := range results {
		if pathScopeMatches(result.FilePath, scopes) {
			kept = append(kept, result)
		}
	}
	if len(kept) == 0 {
		kept = results
	}
	if topK > 0 && len(kept) > topK {
		kept = kept[:topK]
	}
	return kept
}
