package cli

import "testing"

import "github.com/entireio/entire-graph/internal/sem"

func TestPathScopeMatchesFormsTheRecordedGrepsUse(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name  string
		path  string
		scope string
		want  bool
	}{
		{"exact file", "tests/Validation/ValidationValidatorTest.php", "tests/Validation/ValidationValidatorTest.php", true},
		{"directory with trailing slash", "tests/Validation/ValidationValidatorTest.php", "tests/Validation/", true},
		{"directory without trailing slash", "tests/Validation/ValidationValidatorTest.php", "tests/Validation", true},
		{"sibling directory does not match", "tests/Auth/GuardTest.php", "tests/Validation", false},
		{"prefix must stop at a separator", "tests/ValidationExtras/X.php", "tests/Validation", false},
		{"glob over the full path", "packages/runtime-core/src/hydration.ts", "packages/*/src/*.ts", true},
		{"bare glob falls back to the basename", "internal/cli/def_test.go", "*_test.go", true},
		{"bare glob that does not match the basename", "internal/cli/def.go", "*_test.go", false},
		{"dot-slash prefixes are normalised", "./lib/fluent/plugin/output.rb", "lib/fluent", true},
		{"empty scope is ignored", "lib/x.rb", "", false},
	}
	for _, testCase := range cases {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			if got := pathScopeMatches(testCase.path, []string{testCase.scope}); got != testCase.want {
				t.Fatalf("pathScopeMatches(%q, %q) = %v, want %v",
					testCase.path, testCase.scope, got, testCase.want)
			}
		})
	}
}

func TestPathScopeMatchesAnyOfSeveralScopes(t *testing.T) {
	t.Parallel()
	// `grep -rn "run_state\|fail_state" --include="*.py" lib/ test/ bin/` names three roots at once.
	scopes := []string{"lib", "test", "bin"}
	if !pathScopeMatches("test/units/executor/test_play_iterator.py", scopes) {
		t.Fatal("a path under the second scope should match")
	}
	if pathScopeMatches("docs/rst/index.rst", scopes) {
		t.Fatal("a path under none of the scopes must not match")
	}
}

func TestApplyPathScopeKeepsOnlyInScopeAndRenumbers(t *testing.T) {
	t.Parallel()
	results := []sem.SearchResult{
		{Rank: 1, FilePath: "internal/sem/search_cache.go"},
		{Rank: 2, FilePath: "internal/gitutil/worktree.go"},
		{Rank: 3, FilePath: "internal/gitutil/git.go"},
	}
	got := applyPathScope(results, []string{"internal/gitutil"}, 8)
	if len(got) != 2 {
		t.Fatalf("expected the two in-scope results, got %d", len(got))
	}
	if got[0].FilePath != "internal/gitutil/worktree.go" || got[1].FilePath != "internal/gitutil/git.go" {
		t.Fatalf("wrong results kept: %+v", got)
	}
	// Ranks must restart at 1: a payload opening at "2." reads as one that lost its top hit.
	if got[0].Rank != 1 || got[1].Rank != 2 {
		t.Fatalf("ranks not renumbered: %d, %d", got[0].Rank, got[1].Rank)
	}
}

func TestApplyPathScopeNeverReturnsEmpty(t *testing.T) {
	t.Parallel()
	// A scope matching nothing is a narrowing hint that failed, not a reason to answer nothing.
	// Empty graph output is the measured worst case: 3 of 4 live sessions abandoned the tool
	// permanently after a single refusal.
	results := []sem.SearchResult{
		{Rank: 1, FilePath: "internal/sem/search_cache.go"},
		{Rank: 2, FilePath: "internal/gitutil/worktree.go"},
	}
	got := applyPathScope(results, []string{"no/such/dir"}, 8)
	if len(got) != 2 {
		t.Fatalf("expected the unscoped head as a fallback, got %d results", len(got))
	}
}

func TestApplyPathScopeTruncatesToCallerTopK(t *testing.T) {
	t.Parallel()
	// The fetch is deliberately over-sized so the filter has something to keep; the caller must
	// still get back only the top-k it asked for.
	results := make([]sem.SearchResult, 0, 30)
	for index := 0; index < 30; index++ {
		results = append(results, sem.SearchResult{Rank: index + 1, FilePath: "lib/a.rb"})
	}
	got := applyPathScope(results, []string{"lib"}, 5)
	if len(got) != 5 {
		t.Fatalf("expected truncation to top-k 5, got %d", len(got))
	}
}

func TestParseSearchFlagsAcceptsRepeatedPath(t *testing.T) {
	t.Parallel()
	flags, rest, err := parseSearchFlags([]string{
		"--query", "retry backoff", "--path", "lib/", "--path", "test/",
	})
	if err != nil {
		t.Fatalf("parseSearchFlags: %v", err)
	}
	if len(rest) != 0 {
		t.Fatalf("unexpected positional args: %v", rest)
	}
	if len(flags.PathScope) != 2 || flags.PathScope[0] != "lib/" || flags.PathScope[1] != "test/" {
		t.Fatalf("PathScope = %v, want [lib/ test/]", flags.PathScope)
	}
}

