package cli

import (
	"fmt"
	"os"
	"strings"

	"github.com/entireio/entire-graph/internal/sem"
)

// envSearchAnswersFirst promotes the answer blocks (covering-test note, VERIFY command) above the
// low-rank ranked hits.
//
// WHY THIS EXISTS. The renderer's ordering assumes the reader consumes the payload. Measured
// across the 33 rep50 payloads that were logged, it does not:
//
//	payload length            median 98 lines
//	agent truncation          `head -50` on 68 of 94 graph calls (72%), median cut 50 lines
//	VERIFY block position     median line 80  -> delivered in 2 of the 8 payloads that had one
//	covering-test position    median line 62  -> delivered in 3 of 8
//	rank 4 / rank 5 bodies    median lines 52 / 70, inside the cut 45% / 32%
//	rank 3+ read rate         0-11% (search_outline.go's act-rate measurement)
//
// So the two blocks that answer "what proves this edit" and "how do I run it" are generated and
// then discarded by the reader, while source nobody opens occupies the lines they needed.
//
// This is NOT a byte change and must not be read as one. Bytes past the reader's cut are never
// billed — they are truncated before entering context — so trimming the tail saves nothing and
// promoting the blocks costs nothing. The payload is byte-identical either way; only the contents
// of the first ~50 lines differ.
//
// Default OFF so the change is a flag flip in an A/B and the shipped payload is unchanged until a
// gate says otherwise.
const envSearchAnswersFirst = "EG_ANSWERS_FIRST"

func searchAnswersFirst() bool {
	return strings.TrimSpace(os.Getenv(envSearchAnswersFirst)) == "1"
}

// writeSearchAnswerBlocks emits the covering-test note and the VERIFY command, in that order.
//
// Order within the pair is unchanged from the late path: the note says what the code must do and
// VERIFY is the command that proves it, and they are one thought. Only their position relative to
// the ranked hits moves.
func writeSearchAnswerBlocks(out interface{ Write([]byte) (int, error) }, response sem.SearchResponse) error {
	wrote := false
	if block := sem.RenderSearchCoverageNote(response.CoverageNote); len(block) > 0 {
		if _, err := out.Write(block); err != nil {
			return err
		}
		wrote = true
	}
	if block := sem.RenderSearchVerifyCommand(response.VerifyCommand); len(block) > 0 {
		if _, err := out.Write(block); err != nil {
			return err
		}
		wrote = true
	}
	if wrote {
		fmt.Fprintln(out)
	}
	return nil
}
